; Written by hand, not generated by c64-source: source.ts generate keeps this file.
; Boot: shows the Melbourne House title picture, plays the speech sample of the original
; loading stage, then starts the game through the generated loader.
;
; The original disk loaded the game in parts. While the parts loaded, it showed the title
; picture (file M.PICTURE) and played a 1-bit sample (M.TSOUND) with the tiny player
; M.MYTINY and its period table M.SPCHTBL. These files are not part of the game image.
; src/loading_stage/ is their source (knowledge space bank1); the files of the 2010 disk are
; in original/releases/2010_loading/. The 2010 loader copies the picture to VIC bank 3 and
; calls the sample player at $9000. This boot does the same.
;
; The release PRG is one packed file (c64-packer) with these parts, in load order:
;   build/fist_v1_loader.prg            $0801  the generated loader of the game (stage 2)
;   original/releases/2010_loading/segment-2000-35ff.prg   the sample, over stage 2
;   original/releases/2010_loading/segment-9000-910f.prg   the sample player
;   original/releases/2010_loading/segment-9800-9aff.prg   the period table
;   build/boot_stash.prg                $9b00  the bytes of stage 2 at $2000-$35ff
;   build/boot.prg                      $c000  this file: colour data, M.PRERUN, the boot code, screen RAM
;   build/boot_bitmap.prg               $e000  the bitmap of the picture
; Entry: boot_start ($c600). Build steps: see README.md, section "Build".
;
; The boot shows the picture, plays the sample once, and then waits 8 seconds, or less
; when a key or a fire button is pressed. Then it stops the interrupts of the sample player,
; puts the stash back to $2000-$35ff and jumps to the unpacker of stage 2 at $080d.

!cpu 6510

boot_colour_ram    = $d800
boot_stash         = $9b00              ; boot_stash.asm: stage 2 bytes of $2000-$35ff
boot_stash_dest    = $2000
boot_stash_pages   = $16                ; $1600 bytes: $2000-$35ff
boot_loader_entry  = $080d              ; the unpacker of the generated loader (SYS 2061)
boot_wait_frames   = 400                ; 8 seconds (PAL)
tsound_entry       = $9000              ; loading_stage: plays the sample and returns at its end
prerun_entry       = $c400              ; loading_stage: M.PRERUN, an RTS
boot_src           = $fb                ; 2 bytes
boot_dst           = $fd                ; 2 bytes
boot_count         = $02                ; 2 bytes: frames left

* = $c000
; The colour RAM data of the picture (M.PICTURE $8328-$870f): the boot copies it to $d800.
boot_picture_colour
        !binary "segment-6000-870f.prg", 1000, 2 + 9000

* = $c400
; M.PRERUN, as the original loading stage left it at $c400.
        !binary "segment-c400-c435.prg", , 2

* = $c600
!zone boot {
boot_start
        sei
        lda #$03                        ; border: cyan, as the 2010 loader sets it
        sta $d020
        lda #$01                        ; background: white
        sta $d021
        lda #$00                        ; VIC bank 3 ($c000-$ffff)
        sta $dd00
        lda #$38                        ; screen $cc00, bitmap $e000
        sta $d018
        lda #$18                        ; multicolour
        sta $d016
        ldx #0
.colour lda boot_picture_colour,x       ; 1000 bytes: four pages of 250
        sta boot_colour_ram,x
        lda boot_picture_colour+250,x
        sta boot_colour_ram+250,x
        lda boot_picture_colour+500,x
        sta boot_colour_ram+500,x
        lda boot_picture_colour+750,x
        sta boot_colour_ram+750,x
        inx
        cpx #250
        bne .colour
        lda #$3b                        ; bitmap mode, screen on
        sta $d011
        cli
        jsr tsound_entry                ; M.MYTINY: plays M.TSOUND once
        sei
        lda #$7f                        ; the sample player leaves CIA1 timer B on
        sta $dc0d
        lda #$00
        sta $dc0f
        lda $dc0d
        lda #<boot_wait_frames
        sta boot_count
        lda #>boot_wait_frames
        sta boot_count+1
.frame  lda $d012                       ; wait for the next frame
        cmp #$f8
        bne .frame
.line   lda $d012
        cmp #$f8
        beq .line
        lda #$00                        ; all keyboard columns
        sta $dc00
        lda $dc01
        and #$1f
        cmp #$1f
        bne .go                         ; a key, or fire of port 1
        lda #$ff
        sta $dc00
        lda $dc00
        and #$10
        beq .go                         ; fire of port 2
        lda boot_count
        bne +
        dec boot_count+1
+       dec boot_count
        lda boot_count
        ora boot_count+1
        bne .frame
.go     lda #$ff
        sta $dc00
        jsr prerun_entry                ; as the loader of the 2010 disk does
        lda #$36                        ; BASIC ROM off: the stash goes up to $b0ff, and
        sta $01                         ; tsound_stop_irq switched the BASIC ROM on again
        lda #<boot_stash
        sta boot_src
        lda #>boot_stash
        sta boot_src+1
        lda #<boot_stash_dest
        sta boot_dst
        lda #>boot_stash_dest
        sta boot_dst+1
        ldx #boot_stash_pages
        ldy #0
.copy   lda (boot_src),y
        sta (boot_dst),y
        iny
        bne .copy
        inc boot_src+1
        inc boot_dst+1
        dex
        bne .copy
        lda #$37                        ; the unpacker of stage 2 starts as after RUN:
        sta $01                         ; BASIC, KERNAL and I/O in
        jmp boot_loader_entry
}

* = $cc00
; The screen RAM of the picture (M.PICTURE $7f40-$8327).
boot_picture_screen
        !binary "segment-6000-870f.prg", 1000, 2 + 8000
